import { esc, human, date, safeUrl, storyUrl, effective, mediaFor, badge, stateLabel, nextAction, image, empty, external, sectionHeading, storyCard, blockers, draftNotice, fieldDisabled, proposalControl } from './components.js';
import { directionView, creativeBriefSummary } from './direction.js';

const allStories = state => state.workspace?.stories || [];
const filtered = (stories, query) => !query ? stories : stories.filter(s => `${s.title} ${s.subject} ${s.hook} ${s.id}`.toLowerCase().includes(query.toLowerCase()));
const count = (stories, group) => stories.filter(story => stateLabel(story).group === group).length;
const tabs = [['overview', 'Overview'], ['direction', 'Direction'], ['research', 'Research'], ['images', 'Images'], ['carousel', 'Carousel'], ['caption', 'Caption'], ['music', 'Music'], ['publishing', 'Publishing']];
const aggregationLabel = value => ({ mean_of_observed_post_rates: 'Average of measured post rates', sum_of_observed_post_values: 'Total across measured posts' })[value] || 'Reported measurement';

function pageHeader(kicker, title, description, action = '') {
  return `<div class="page-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1>${esc(title)}</h1><p class="page-description">${esc(description)}</p></div>${action}</div>`;
}

export function home(state) {
  const stories = allStories(state);
  const ongoing = stories.filter(s => stateLabel(s).group !== 'archive');
  const feature = ongoing.find(s => mediaFor(s).length) || ongoing.find(s => s.media?.length) || stories[0];
  const rights = stories.filter(s => effective(s).selectedAssetIds.length && s.rightsStatus !== 'complete').length;
  const draftCount = stories.filter(s => s.publishing?.observed === 'buffer_unscheduled_draft').length;
  const review = stories.filter(s => s.publishing?.requiresReview || s.publishing?.multipleHandoffs || s.localDraft?.stale);
  const featuredPhoto = feature && (mediaFor(feature)[0] || feature.media?.[0]);
  return `<section class="home-intro"><div><p class="eyebrow">An independent archival publication</p><h1>The edit,<br><em>in motion.</em></h1><p class="intro-deck">A clear desk for extraordinary stories.<br>Research, photographs and the decisions between them.</p></div><div class="issue-mark"><span>M / I</span><small>THE EDITORIAL WORKSPACE</small><p>Source-led.<br>Independently made.</p></div></section>
    <div class="stats-row"><a href="#/pipeline"><strong>${ongoing.length}</strong><span>Stories in progress</span></a><a href="#/publishing"><strong>${draftCount}</strong><span>Existing Buffer drafts</span></a><a href="#/library"><strong>${rights}</strong><span>Selected-image rights reviews</span></a><a href="#/publishing"><strong>${review.length}</strong><span>Handoffs to reconcile</span></a></div>
    ${feature ? `<section class="feature-story"><a class="feature-image" href="${storyUrl(feature.id)}" aria-label="Continue ${esc(feature.title)}">${image(featuredPhoto, { eager: true })}</a><div class="feature-copy"><p class="eyebrow">On the editorial desk · ${esc(feature.subject || feature.format)}</p><h2><a href="${storyUrl(feature.id)}">${esc(feature.title)}</a></h2><p>${esc(feature.hook || nextAction(feature).reason)}</p><div class="feature-facts">${badge(stateLabel(feature).label, stateLabel(feature).tone)}<span>${feature.media?.length || 0} image candidates</span></div><a class="button button-dark" href="${storyUrl(feature.id, nextAction(feature).tab)}">${esc(nextAction(feature).label)} <span aria-hidden="true">→</span></a></div></section>` : empty('A clean editorial desk', 'No existing stories were returned by the connected source. Refresh the snapshot to check access.')}
    <section>${sectionHeading('Stories taking shape', 'Continue an existing story without moving between backend workflows.', '<a class="text-link" href="#/pipeline">View the pipeline →</a>')}<div class="story-grid">${ongoing.filter(s => s.id !== feature?.id).slice(0, 4).map(s => storyCard(s, { compact: true })).join('') || empty('No other active stories', 'The existing story above is the current work in progress.')}</div></section>
    <div class="two-column"><section class="paper-panel">${sectionHeading('Attention, before another handoff')} ${review.length ? `<ul class="attention-list">${review.slice(0, 5).map(s => `<li><a href="${storyUrl(s.id, 'publishing')}"><strong>${esc(s.title)}</strong><span>${s.localDraft?.stale ? 'Source changed since local draft' : s.publishing?.multipleHandoffs ? 'Multiple provider handoffs recorded' : 'Provider and archive evidence need review'} →</span></a></li>`).join('')}</ul>` : '<p class="muted">No additional reconciliation alerts were returned in this snapshot. Publishing decisions still require review.</p>'}</section><section class="paper-panel">${sectionHeading('Recent editorial activity', 'Source events and local revisions, with their recorded times.')} ${activity(state.workspace.activity || [])}</section></div>`;
}

function activity(items) {
  return items.length ? `<ol class="activity-list">${items.slice(0, 7).map(item => `<li><span class="activity-dot" aria-hidden="true"></span><div>${item.storyId ? `<a href="${storyUrl(item.storyId)}">${esc(item.summary)}</a>` : `<strong>${esc(item.summary)}</strong>`}<small>${esc(date(item.at))} ET · ${esc(human(item.type))}</small></div></li>`).join('')}</ol>` : '<p class="muted">No timestamped activity was supplied. Events are not inferred from story order.</p>';
}

function existingSourceNotes(story) {
  const notes = [['Founder notes', story.sourceNotes], ['Production direction', story.productionNotes], ['Source review notes', story.sourceReviewNotes]].filter(([, value]) => typeof value === 'string' && value.trim());
  return notes.length ? `<section class="editorial-panel existing-source-notes"><div class="section-heading"><div><h2>Existing n8n notes</h2><p>Editorial decisions already recorded in the source system. These read-only notes are separate from the local proposal.</p></div></div>${notes.map(([label, value]) => `<details open><summary>${label}</summary><p>${esc(value)}</p></details>`).join('')}</section>` : '';
}

export function pipeline(state) {
  const stories = filtered(allStories(state), state.search);
  const groups = [['all', 'All stories'], ['research', 'Research'], ['production', 'In production'], ['publishing', 'Publishing'], ['archive', 'Reported published']];
  const visible = state.pipelineGroup === 'all' ? stories : stories.filter(s => stateLabel(s).group === state.pipelineGroup);
  return `${pageHeader('The story pipeline', 'Every story, in view.', 'Follow the existing publication from first research to a verified outcome.')}
    <div class="filter-bar"><div class="filter-chips" aria-label="Filter stories by stage">${groups.map(([key, label]) => `<button class="filter-chip ${state.pipelineGroup === key ? 'active' : ''}" data-action="pipeline-filter" data-value="${key}" aria-pressed="${state.pipelineGroup === key}">${label}<span>${key === 'all' ? stories.length : count(stories, key)}</span></button>`).join('')}</div><span class="small muted">${visible.length} ${visible.length === 1 ? 'story' : 'stories'}</span></div>
    <div class="pipeline-list">${visible.length ? visible.map((story, index) => { const status = stateLabel(story); const action = nextAction(story); return `<article class="pipeline-row"><span class="row-number">${String(index + 1).padStart(2, '0')}</span><a class="pipeline-thumb" href="${storyUrl(story.id)}" aria-label="Open ${esc(story.title)}">${image(mediaFor(story)[0] || story.media?.[0])}</a><div class="pipeline-title"><p class="eyebrow">${esc(story.subject || story.format)}</p><h2><a href="${storyUrl(story.id)}">${esc(story.title)}</a></h2><small>${esc(story.id)}${story.localDraft ? ' · local draft saved' : ''}</small></div><div class="pipeline-status">${badge(status.label, status.tone)}<span>${effective(story).selectedAssetIds.length} / ${story.targetSlideCount || '—'} slides selected</span><span>${(story.blockers || []).length} recorded blockers</span></div><a class="row-action" href="${storyUrl(story.id, action.tab)}">${esc(action.label)} <span aria-hidden="true">→</span></a></article>`; }).join('') : empty('No stories in this view', 'Try another editorial stage or clear the search.')}</div>`;
}

export function storyWorkspace(state, story, tab) {
  const content = { overview: storyOverview, direction: directionView, research: storyResearch, images: storyImages, carousel: storyCarousel, caption: storyCaption, music: storyMusic, publishing: storyPublishing };
  if (!content[tab]) tab = 'overview';
  const status = stateLabel(story);
  return `<a class="back-link" href="#/pipeline">← All stories</a><div class="story-heading"><div><p class="eyebrow">${esc(story.subject || 'Editorial story')} · ${esc(story.id)}</p><h1>${esc(story.title)}</h1><div class="story-meta">${badge(status.label, status.tone)}<span>${story.packageVersion ? `Production package v${story.packageVersion}` : 'No production package recorded'}</span><span>${esc(human(story.format))}</span></div></div><div class="story-header-actions">${proposalControl(story)}<button class="text-button" data-action="draft-history" data-story="${esc(story.id)}">Local version history</button></div></div>
    ${draftNotice(story)}<nav class="story-tabs" aria-label="Story workspace">${tabs.map(([id, label]) => `<a href="${storyUrl(story.id, id)}" ${id === tab ? 'aria-current="page"' : ''}>${label}${id === 'images' ? `<small>${story.media?.length || 0}</small>` : ''}</a>`).join('')}</nav>
    <div class="story-workspace">${content[tab](state, story)}</div>`;
}

function storyOverview(state, story) {
  const selected = mediaFor(story);
  const action = nextAction(story);
  return `<div class="workspace-main"><section class="editorial-panel"><p class="eyebrow">The editorial direction</p><h2 class="serif-heading">${esc(story.hook || story.title)}</h2><p class="body-copy">${esc(story.caption || 'This existing story has no saved caption yet. Use the caption workspace to develop a local proposal.')}</p><div class="story-direction-links"><a class="text-link" href="${storyUrl(story.id, 'direction')}">Refine the creative direction →</a><a class="text-link" href="${storyUrl(story.id, 'caption')}">Develop the caption →</a></div></section>${existingSourceNotes(story)}<section>${sectionHeading('The selected photographs', `${selected.length} ordered images in the ${story.localDraft ? 'local draft' : 'source package'}.`, `<a class="text-link" href="${storyUrl(story.id, 'carousel')}">Review the sequence →</a>`)}${selected.length ? `<div class="contact-strip">${selected.slice(0, 6).map((asset, index) => image(asset, { index, storyId: story.id })).join('')}</div>` : empty('The photographs come first', 'Browse this story’s existing candidates and build a local sequence.', `<a class="button button-dark" href="${storyUrl(story.id, 'images')}">Review image candidates →</a>`)}</section><section class="editorial-panel"><div class="section-heading"><div><h2>Editor’s working notes</h2><p>Private notes for this story. Saved locally, without changing n8n.</p></div><button class="text-button" data-action="notes-template" data-story="${esc(story.id)}" ${fieldDisabled(story)}>Add research checklist</button></div><label class="sr-only" for="editor-notes">Editor’s working notes</label><textarea id="editor-notes" data-draft-field="notes" data-story="${esc(story.id)}" rows="7" placeholder="The strongest angle, unresolved questions, image decisions…" ${fieldDisabled(story)}>${esc(effective(story).notes)}</textarea></section></div><aside class="workspace-aside"><section class="next-action"><p class="eyebrow">Next editorial action</p><h2>${esc(action.label)}</h2><p>${esc(action.reason)}</p><a class="button button-dark" href="${storyUrl(story.id, action.tab)}">Continue →</a></section><section class="aside-block"><h3>Production readiness</h3>${blockers(story)}</section><section class="aside-block"><h3>One story, one identity</h3><p>Research, media and handoffs below all refer to the existing story record.</p><code>${esc(story.id)}</code><p class="small muted">Local proposals preserve the source revision so edits can be reviewed before integration.</p></section></aside>`;
}

function storyResearch(state, story) {
  const claims = story.research || [];
  const sourceIssues = story.intelligence?.sourceIssues || [];
  return `<div class="workspace-main">${sectionHeading('A story built on sources', 'Recorded claims and citations from the existing dossier. Source labels are not new verification.')}${claims.length ? `<div class="research-list">${claims.map((claim, i) => `<article class="research-claim"><span class="claim-number">${String(i + 1).padStart(2, '0')}</span><div><p>${esc(claim.claim)}</p><div class="research-meta">${badge(claim.claimType === 'verified_fact' ? 'Recorded as fact' : human(claim.claimType))}${external(claim.url, claim.sourceName || 'Original source')}</div></div></article>`).join('')}</div>` : empty('The dossier needs evidence', 'No structured source claims are attached to this story. The existing Founder Studio remains available for source-led research.')}
    ${existingSourceNotes(story)}${sourceIssues.length ? `<section class="notice warning"><h3>Source review</h3><ul>${sourceIssues.map(issue => `<li>${esc(issue.message || human(issue.code || issue))}</li>`).join('')}</ul></section>` : ''}
    <section class="editorial-panel"><h2>Research notes</h2><p class="muted">Separate evidence from interpretation. These notes stay in your local proposal.</p><label class="sr-only" for="research-notes">Research notes</label><textarea id="research-notes" data-draft-field="notes" data-story="${esc(story.id)}" rows="9" ${fieldDisabled(story)}>${esc(effective(story).notes)}</textarea></section></div><aside class="workspace-aside"><section class="aside-block"><p class="eyebrow">Fact-checking boundary</p><h3>Keep the evidence visible.</h3><p>This workspace displays the dossier’s stored claims and source links. It has not independently revisited source pages or verified their claims.</p><p>Record the original passage, date and creator before moving a claim into the final caption.</p></section><section class="aside-block"><h3>Current review state</h3>${badge(story.sourceClaimsReviewed ? 'Source review recorded' : 'Source review not complete', story.sourceClaimsReviewed ? 'good' : 'warn')}<p>Recorded review does not clear image reproduction rights.</p></section></aside>`;
}

function assetCard(story, asset, selected, compared = false) {
  return `<article class="asset-card ${selected ? 'selected' : ''}">${image(asset, { storyId: story.id })}<div class="asset-copy"><p class="eyebrow">${esc(asset.creator || asset.provider || 'Creator unrecorded')}</p><h3><button class="title-button" data-action="inspect" data-story="${esc(story.id)}" data-asset="${esc(asset.id)}">${esc(asset.title || 'Untitled source image')}</button></h3><div class="asset-meta">${asset.localReview?badge(`Your ${human(asset.localReview.decision)}`,asset.localReview.decision==='reject'?'warn':'quiet'):''}${badge(asset.rightsStatus === 'cleared' ? 'Clearance recorded' : 'Rights pending', asset.rightsStatus === 'cleared' ? 'good' : 'warn')}<span>${asset.width && asset.height ? `${esc(asset.width)} × ${esc(asset.height)}` : 'Dimensions not recorded'}</span></div><div class="asset-actions"><button class="small-button ${selected ? 'is-selected' : ''}" data-action="toggle-asset" data-story="${esc(story.id)}" data-asset="${esc(asset.id)}" aria-pressed="${selected}" ${fieldDisabled(story)}>${selected ? '✓ In local sequence' : '+ Add to sequence'}</button><button class="text-button" data-action="compare-asset" data-story="${esc(story.id)}" data-asset="${esc(asset.id)}" aria-pressed="${compared}">${compared ? '✓ Compare' : 'Compare'}</button></div></div></article>`;
}

function storyImages(state, story) {
  const selected = effective(story).selectedAssetIds;
  return `<div class="workspace-full">${sectionHeading('Choose the photographs', 'Select existing candidates for a local carousel proposal. Selection does not grant publication rights.', `<a class="button button-light" href="${storyUrl(story.id, 'carousel')}">Review ${selected.length} slides →</a>`)}<div class="notice subtle"><strong>Provenance stays with every image.</strong><p>Open an image to review its creator, source, recorded license and rights status. Previews may be low-resolution or restricted.</p></div><div class="asset-grid">${story.media?.length ? story.media.map(asset => assetCard(story, asset, selected.includes(asset.id), state.compared.some(c => c.storyId === story.id && c.assetId === asset.id))).join('') : empty('No candidates attached', 'Continue sourcing in the existing Founder Studio. This workspace does not fetch arbitrary image URLs.')}</div></div>`;
}

function storyCarousel(state, story) {
  const selected = mediaFor(story);
  const current = effective(story);
  const target = story.targetSlideCount || null;
  return `<div class="workspace-main">${sectionHeading('Build the visual sequence', 'Drag slides or use the move controls. Order is saved only in your local proposal.', `<div class="carousel-actions"><button class="small-button" data-action="rehearse-story" data-story="${esc(story.id)}" ${selected.length ? '' : 'disabled'}>Rehearse carousel</button><a class="text-link" href="${storyUrl(story.id, 'images')}">Add photographs →</a></div>`)}${selected.length ? `<ol class="carousel-list" aria-label="Ordered carousel slides">${selected.map((asset, index) => `<li class="carousel-slide" draggable="${!story.localDraft?.stale}" data-slide-index="${index}" data-story="${esc(story.id)}"><span class="drag-handle" aria-hidden="true">⠿</span>${image(asset, { index, storyId: story.id })}<div class="slide-copy"><p class="eyebrow">${index === 0 ? 'Opening image' : `Slide ${index + 1}`}</p><h3>${esc(asset.title || 'Untitled image')}</h3><p>${esc(asset.creator || 'Creator unrecorded')}</p>${badge(asset.rightsStatus === 'cleared' ? 'Clearance recorded' : 'Rights pending', asset.rightsStatus === 'cleared' ? 'good' : 'warn')}</div><div class="slide-controls"><button class="icon-button" data-action="move-slide" data-story="${esc(story.id)}" data-index="${index}" data-direction="-1" aria-label="Move slide ${index + 1} earlier" ${index === 0 || story.localDraft?.stale ? 'disabled' : ''}>↑</button><button class="icon-button" data-action="move-slide" data-story="${esc(story.id)}" data-index="${index}" data-direction="1" aria-label="Move slide ${index + 1} later" ${index === selected.length - 1 || story.localDraft?.stale ? 'disabled' : ''}>↓</button><button class="icon-button remove-slide" data-action="toggle-asset" data-story="${esc(story.id)}" data-asset="${esc(asset.id)}" aria-label="Remove slide ${index + 1} from local sequence" ${fieldDisabled(story)}>×</button></div></li>`).join('')}</ol>` : empty('Start with the opening photograph', 'Choose a candidate from the story’s existing image library, then shape the narrative one slide at a time.', `<a class="button button-dark" href="${storyUrl(story.id, 'images')}">Choose images →</a>`)}
    <section class="editorial-panel"><h2>The caption beside the sequence</h2><p class="body-copy">${esc(current.caption || 'No caption has been saved.')}</p><a class="text-link" href="${storyUrl(story.id, 'caption')}">Edit the local caption →</a></section></div><aside class="workspace-aside"><section class="aside-block"><p class="eyebrow">Carousel review</p><h3>${selected.length}${target ? ` / ${target}` : ''} slides selected</h3><ul class="check-list"><li>${selected.length ? '✓' : '○'} At least one photograph</li><li>${!target || selected.length === target ? '✓' : '○'} ${target ? `Source target: ${target} slides` : 'No source slide target recorded'}</li><li>${selected.every(a => a.width === 1080 && a.height === 1350) && selected.length ? '✓' : '○'} 1080 × 1350 dimensions recorded</li><li>${selected.every(a => a.rightsStatus === 'cleared') && selected.length ? '✓' : '○'} Per-image clearance recorded</li></ul><p class="small muted">These are record checks, not a decoded JPG/export verification. Local proposals do not generate or upload files.</p></section><section class="aside-block"><h3>Ready for a considered review.</h3><p>Use the existing n8n export flow after approving the selection. This development workspace can download the local edit proposal.</p>${proposalControl(story, 'Download proposal ↗')}</section></aside>`;
}

function storyCaption(state, story) {
  const caption = effective(story).caption;
  return `<div class="workspace-main">${sectionHeading('Make every word earn its place.', 'Edit a private local proposal while retaining the original caption in n8n.')}<label class="field-label" for="caption-editor">Local caption draft</label><textarea class="caption-editor" id="caption-editor" data-draft-field="caption" data-story="${esc(story.id)}" rows="13" ${fieldDisabled(story)}>${esc(caption)}</textarea><div class="caption-toolbar"><span data-caption-count class="${[...caption].length > 2200 ? 'error-text' : ''}">${[...caption].length} / 2,200 characters</span><span>Autosaves locally</span></div><p data-caption-warning class="inline-warning" ${[...caption].length <= 2200 && !/INTERNAL[\s\S]{0,60}TEST|DO\s+NOT\s+PUBLISH/iu.test(caption) ? 'hidden' : ''}>Review caption length or internal-test markers before any handoff.</p>
    <div data-caption-checks>${captionChecks(story)}</div><details class="source-caption"><summary>Compare with the saved source caption</summary><p class="body-copy">${esc(story.caption || 'No source caption recorded.')}</p></details></div><aside class="workspace-aside"><section class="aside-block"><h3>The editorial pass</h3><ol class="numbered-notes"><li>Lead with the specific, unusual fact.</li><li>Keep the photographer and historical context visible.</li><li>Remove instructions to the production team.</li><li>Check each factual claim against its original source.</li><li>Preserve credits and permission requirements.</li></ol></section><section class="aside-block"><h3>Keep sources close.</h3><p>${(story.research || []).length} recorded source claims are attached to this story.</p><a class="text-link" href="${storyUrl(story.id, 'research')}">Review research →</a></section></aside>`;
}

export function captionChecks(story) {
  const issues = story.intelligence?.caption?.issues || [];
  return `<section class="editorial-panel"><h2>Editorial checks</h2>${issues.length ? `<ul class="editorial-checks">${issues.map(issue => `<li>${badge(human(issue.severity || 'review'), issue.severity === 'error' ? 'warn' : '')}<span>${esc(issue.message || human(issue.code))}</span></li>`).join('')}</ul>` : '<p class="muted small">No additional text-check flags were supplied for the last saved context.</p>'}<p class="small muted">Checks reflect the last saved local or source context. They support editorial judgment and do not fact-check the caption.</p></section>`;
}

function storyMusic(state, story) {
  const selection = effective(story).musicSelection;
  const recommendations = story.musicRecommendations || story.intelligence?.musicRecommendations || [];
  return `<div class="workspace-main">${sectionHeading('Find the story’s sound.', 'Recommendations use editorial text and metadata. No audio or image-pixel analysis is implied.')}<section class="selected-track"><span class="record-icon" aria-hidden="true">◎</span><div><p class="eyebrow">${story.localDraft?.musicSelection ? 'Local sound direction' : 'Saved sound direction'}</p><h2>${esc(selection?.track || 'No track selected')}</h2><p>${esc(selection?.artist || 'Choose a recommendation or record a direction below.')}</p></div></section><div class="track-list">${recommendations.length ? recommendations.map((track, index) => `<article class="track"><span class="track-index">${String(index + 1).padStart(2, '0')}</span><div><h3>${esc(track.track || track.title)}</h3><p>${esc(track.artist)}</p><small>${esc(track.reason || track.reasons?.join('; ') || 'Suggested from this story’s editorial metadata.')}</small></div><button class="small-button" data-action="choose-track" data-story="${esc(story.id)}" data-index="${index}" ${fieldDisabled(story)}>${selection?.track === track.track && selection?.artist === track.artist ? '✓ Selected' : 'Choose locally'}</button></article>`).join('') : empty('No recommendations supplied', 'The existing source catalog has not returned a ranked selection for this story.')}</div><section class="editorial-panel"><h2>Record another direction</h2><p class="muted">A local editorial preference, not confirmation of Instagram availability.</p><form data-form="music" data-story="${esc(story.id)}"><div class="field-pair"><label>Track<input name="track" maxlength="200" required value="${esc(selection?.track || '')}" ${fieldDisabled(story)}></label><label>Artist<input name="artist" maxlength="200" required value="${esc(selection?.artist || '')}" ${fieldDisabled(story)}></label></div><button class="button button-dark" type="submit" ${fieldDisabled(story)}>Save local direction</button></form></section></div><aside class="workspace-aside"><section class="aside-block"><h3>Check it in Instagram.</h3><p>Music availability and usage rights can vary by account, region and purpose. Confirm the actual track inside Instagram before publication.</p><p>No playback or music licensing is provided by this workspace.</p></section></aside>`;
}

function storyPublishing(state, story) {
  const p = story.publishing || {};
  return `<div class="workspace-main">${sectionHeading('One story. A traceable handoff.', 'Provider observations, manual labels and verified Instagram outcomes stay separate.')}<div class="publishing-summary"><div><small>Provider observation</small><strong>${esc(human(p.observed || 'unknown'))}</strong></div><div><small>Manual lifecycle</small><strong>${esc(human(p.manualStatus || 'active'))}</strong></div><div><small>Instagram verification</small><strong>${p.instagramVerified ? 'Recorded' : 'Not independently verified'}</strong></div></div>
    ${p.multipleHandoffs || p.requiresReview ? '<div class="notice warning"><strong>Reconcile before another handoff.</strong><p>Existing provider activity or incomplete evidence needs review. A repeated send must not create a replacement draft.</p></div>' : ''}<section class="editorial-panel"><h2>Existing provider references</h2>${p.postIds?.length ? `<ul class="reference-list">${p.postIds.map(id => `<li><code>${esc(id)}</code><span>Buffer post reference</span></li>`).join('')}</ul>` : '<p class="muted">No mapped Buffer post IDs were supplied for this story. A missing mapping does not establish that no post exists.</p>'}${(p.reportedInstagramLinks || []).map(link => `<p>${external(link.url, 'Open provider-reported Instagram link')}</p>`).join('')}<p class="small muted">Provider links are reported evidence. They are not a fresh Instagram availability check.</p></section><section class="editorial-panel"><h2>Review a local change proposal</h2><p>Export the current local caption, image order, notes and music direction with its source revision. Integration into n8n remains a separate reviewed change.</p>${proposalControl(story, 'Download proposal ↗', 'button button-dark')}${external('https://rickywelch.app.n8n.cloud/webhook/founder-command-center', 'Open existing Founder Studio', 'text-link inline-gap')}</section></div><aside class="workspace-aside"><section class="aside-block"><p class="eyebrow">Handoff boundary</p><h3>Production sends stay in n8n.</h3><p>This workspace does not create Buffer drafts, schedule, publish, delete, grant rights or change production workflows.</p><p>Review the actual existing draft and per-image permissions in the current production flow.</p></section><section class="aside-block"><h3>Outstanding preparation</h3>${blockers(story)}</section></aside>`;
}

export function library(state) {
  const query = (state.librarySearch || '').toLowerCase();
  const all = allStories(state).flatMap(story => (story.media || []).map(asset => ({ story, asset })));
  const candidates = all.filter(({ story, asset }) => (!query || `${asset.title} ${asset.creator} ${asset.provider} ${story.title}`.toLowerCase().includes(query)) && (state.libraryRights === 'all' || (state.libraryRights === 'cleared' ? asset.rightsStatus === 'cleared' : asset.rightsStatus !== 'cleared')));
  return `${pageHeader('The archival image library', 'Photographs, with a history.', 'Review the existing publication’s image candidates, sources and recorded permissions.')}<div class="library-tools"><label class="search-field"><span aria-hidden="true">⌕</span><input type="search" id="library-search" placeholder="Search photographs, creators or stories" value="${esc(state.librarySearch)}" aria-label="Search image library"></label><label class="select-field">Rights view<select id="library-rights"><option value="all" ${state.libraryRights === 'all' ? 'selected' : ''}>All candidates</option><option value="pending" ${state.libraryRights === 'pending' ? 'selected' : ''}>Rights pending</option><option value="cleared" ${state.libraryRights === 'cleared' ? 'selected' : ''}>Clearance recorded</option></select></label><span class="small muted">${candidates.length} candidates</span></div><div class="asset-grid library-grid">${candidates.length ? candidates.map(({ story, asset }) => assetCard(story, asset, effective(story).selectedAssetIds.includes(asset.id), state.compared.some(c => c.storyId === story.id && c.assetId === asset.id))).join('') : empty('No matching photographs', 'Change the search or rights view. No image clearance is inferred from its source.')}</div>
    <section class="archive-directory">${sectionHeading('Start with the original archive', 'The existing curated directory supports discovery. Each image still needs its own rights review.')}<div class="source-grid">${(state.workspace.imageArchives || []).map(source => `<article class="source-card"><h3>${external(source.url, source.name)}</h3><p>${esc(source.rightsHint || 'Inspect the original image record for rights and reproduction terms.')}</p>${source.searchDomain ? `<small>${esc(source.searchDomain)}</small>` : ''}</article>`).join('') || empty('No archive directory returned', 'Existing source collections will appear when available.')}</div></section>`;
}

export function publishing(state) {
  const stories = filtered(allStories(state), state.search);
  const relevant = stories.filter(s => s.publishing?.postIds?.length || s.publishing?.requiresReview || s.localDraft);
  const mapped = new Set(allStories(state).flatMap(story => story.publishing?.postIds || []));
  const unmapped = (state.workspace.publishingPosts || []).filter(post => !mapped.has(post.id));
  return `${pageHeader('The publishing center', 'Make the handoff visible.', 'A draft, a scheduled post and a verified publication are different outcomes.')}<div class="notice subtle"><strong>The existing production system remains authoritative.</strong><p>Inspect observed handoffs and prepare local proposals here. Scheduling, sending and production edits stay in your approved n8n and Buffer workflow.</p></div><div class="publishing-list">${relevant.length ? relevant.map(story => { const p = story.publishing || {}; const s = stateLabel(story); return `<article class="publishing-row"><a class="publishing-thumb" href="${storyUrl(story.id, 'publishing')}">${image(mediaFor(story)[0] || story.media?.[0])}</a><div><p class="eyebrow">${esc(story.id)}</p><h2><a href="${storyUrl(story.id, 'publishing')}">${esc(story.title)}</a></h2><div class="publishing-facts">${badge(s.label, s.tone)}${p.multipleHandoffs ? badge('Multiple handoffs', 'warn') : ''}<span>${p.postIds?.length || 0} mapped provider IDs</span></div><p>${p.instagramVerified ? 'Independent Instagram evidence recorded.' : 'Instagram outcome has not been independently verified.'}</p></div><a class="row-action" href="${storyUrl(story.id, 'publishing')}">Review handoff →</a></article>`; }).join('') : empty('No handoffs in this view', 'No mapped provider records or local proposals match the current search.')}</div>${unmapped.length ? `<section class="editorial-panel unmapped-records">${sectionHeading('Provider records without a story mapping', 'These real Buffer records are not assigned to an existing story by the source ledger. Captions alone cannot establish a safe match.')}<div class="unmapped-list">${unmapped.map(post => `<article><div><code>${esc(post.id)}</code><div class="publishing-facts">${badge(human(post.status), 'warn')}<span>${post.imageCount ?? '—'} images</span><span>${post.sentAt ? esc(date(post.sentAt)) + ' ET' : 'No sent timestamp'}</span></div></div><p class="small muted">Instagram is not independently verified.</p>${post.externalLink ? external(post.externalLink, 'Provider-reported link') : '<span class="small muted">No external link reported</span>'}</article>`).join('')}</div></section>` : ''}${(state.workspace.intelligence?.duplicates || []).length ? `<section class="editorial-panel">${sectionHeading('Possible repeated story angles', 'Text similarity is a review signal, not proof of duplicate publication.')}<p class="muted">${state.workspace.intelligence.duplicates.length} candidate groups were reported by editorial comparison. Inspect the existing records before creating more stories.</p></section>` : ''}`;
}

export function archive(state) {
  const stories = filtered(allStories(state), state.search).filter(s => ['buffer_sent', 'instagram_posted_verified'].includes(s.publishing?.observed) || s.publishing?.manualStatus === 'posted');
  const verified = stories.filter(s => s.publishing?.instagramVerified);
  return `${pageHeader('The published archive', 'The publication, remembered.', 'Search completed work while retaining the distinction between a manual label, Buffer reporting and Instagram verification.')}<div class="archive-summary"><span><strong>${stories.length}</strong> reported or marked posted stories</span><span><strong>${verified.length}</strong> independently verified Instagram outcomes</span></div><div class="story-grid">${stories.length ? stories.map(story => storyCard(story)).join('') : empty('No published history in this view', 'Try another search. Stories are included only when marked posted or reported sent; no outcomes are fabricated.')}</div>`;
}

function measurementLabel(measurement = {}) {
  if (measurement.oldestAt && measurement.newestAt && measurement.oldestAt !== measurement.newestAt) return `${date(measurement.oldestAt)} – ${date(measurement.newestAt)} ET`;
  if (measurement.newestAt || measurement.oldestAt) return `${date(measurement.newestAt || measurement.oldestAt)} ET`;
  return 'measurement time not supplied';
}

export function analytics(state) {
  const analytics = state.workspace.analytics || {};
  const coverage = analytics.coverage || {};
  const publishing = analytics.publishing || {};
  const metrics = analytics.metrics || [];
  const bottlenecks = analytics.bottlenecks || [];
  const history = publishing.history || [];
  const max = Math.max(1, ...history.map(day => Number(day.count) || 0));
  const range = analytics.measurementRange || {};
  return `${pageHeader('Editorial performance', 'Observe before you infer.', 'Actual provider observations and production bottlenecks. Missing performance metrics remain missing.')}<div class="notice subtle metric-measurement-note"><strong>Snapshot fetched: ${esc(date(analytics.observedAt || state.workspace.source?.bufferObservedAt))} ET</strong><p>Metric measurements: ${esc(measurementLabel(range))}. Fetching the source does not mean its metric values were measured again.</p><p>Measurement timestamps recorded: ${range.knownObservationCount ?? 'not supplied'} · without timestamps: ${range.unknownObservationCount ?? 'not supplied'}. Historical inspiration-account comparisons are not included in these publication metrics.</p></div><div class="stats-row"><div><strong>${coverage.posts ?? '—'}</strong><span>Observed Buffer records</span></div><div><strong>${coverage.sentPosts ?? publishing.sentCount ?? '—'}</strong><span>Reported sent</span></div><div><strong>${coverage.postsWithMetrics ?? '—'}</strong><span>Posts with metrics</span></div><div><strong>${publishing.activeDays ?? '—'}</strong><span>Days with reported sends</span></div></div>
    <section>${sectionHeading('Audience performance', 'Coverage and sample sizes are shown before any interpretation.')}<div class="metric-grid">${metrics.length ? metrics.map(metric => `<article class="metric-card"><p class="eyebrow">${esc(metric.label || human(metric.name))}</p><strong>${metric.available === false || (metric.value ?? metric.total) === null || (metric.value ?? metric.total) === undefined ? 'Not available' : esc(metric.value ?? metric.total)}</strong><p>${esc(metric.unit || '')}</p><small>${metric.sampleSize ?? 0} observations · ${esc(aggregationLabel(metric.aggregation))}</small><small class="metric-as-of">Measured: ${esc(measurementLabel(metric.measurement))}${metric.measurement?.unknownCount !== undefined ? ` · ${metric.measurement.unknownCount} timestamp${metric.measurement.unknownCount === 1 ? '' : 's'} unknown` : ''}</small></article>`).join('') : empty('Performance data is not available', 'No audience metrics were supplied by the authorized data source. Reach and engagement are not inferred from sent-post counts.')}</div></section>
    <div class="two-column"><section class="paper-panel">${sectionHeading('Publishing rhythm', 'Counts are Buffer-reported sends, not verified Instagram reach.')}<div class="history-bars">${history.length ? history.slice(-14).map(day => `<div class="history-row"><span>${esc(day.date)}</span><progress max="${max}" value="${Number(day.count) || 0}" aria-label="${esc(day.date)}: ${Number(day.count) || 0} sends"></progress><strong>${Number(day.count) || 0}</strong></div>`).join('') : '<p class="muted">No dated send history is available.</p>'}</div></section><section class="paper-panel">${sectionHeading('Where work is waiting', 'Resolve the decision, rather than adding another automation.')}<ul class="bottleneck-list">${bottlenecks.length ? bottlenecks.map(item => `<li><div><strong>${esc(item.name || human(item.code))}</strong><small>${esc(item.description || 'Existing records needing review')}</small></div><span>${item.count}</span></li>`).join('') : '<li>No bottleneck summary was supplied.</li>'}</ul></section></div><section class="notice subtle"><strong>Interpretation has limits.</strong><ul>${(analytics.limitations?.length ? analytics.limitations : ['Provider status does not prove a live Instagram outcome.', 'Missing metrics are not zero, and correlations are not causal findings.']).map(limit => `<li>${esc(typeof limit === 'string' ? limit : limit.message)}</li>`).join('')}</ul></section>`;
}

export function compareDialog(state) {
  return `<div class="dialog-heading"><div><p class="eyebrow">Image review</p><h2>Compare the evidence.</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close image comparison">×</button></div><p class="muted">Compare previews and provenance. No visual or rights analysis is inferred.</p><div class="comparison-grid">${state.compared.map(({ storyId, assetId }) => { const story = allStories(state).find(s => s.id === storyId); const asset = story?.media?.find(m => m.id === assetId); return asset ? `<article>${image(asset)}<h3>${esc(asset.title)}</h3><p>${esc(asset.creator || 'Creator unrecorded')}</p>${badge(asset.rightsStatus === 'cleared' ? 'Clearance recorded' : 'Rights pending', asset.rightsStatus === 'cleared' ? 'good' : 'warn')}<p>${external(asset.sourceUrl, 'Original source')}</p><p class="small">${esc(asset.license || 'License not recorded')}</p><a class="text-link" href="${storyUrl(story.id, 'images')}" data-action="close-dialog">Open story →</a></article>` : ''; }).join('')}</div>`;
}

export function assetDialog(story, asset) {
  return `<div class="dialog-heading"><div><p class="eyebrow">Original image record</p><h2>${esc(asset.title || 'Untitled archival image')}</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close image details">×</button></div><div class="asset-detail"><div>${image(asset)}<p class="small muted">Preview only. Authenticity and publication rights require human review.</p><p class="small muted">${asset.localPreview ? `Private local preview · ${esc(asset.localPreview.width)} × ${esc(asset.localPreview.height)}. Identity and rights remain unverified.` : 'External preview loads directly in your browser. Availability may differ by network; a failed preview does not mean the source image is missing.'}</p>
<form data-preview-upload data-story="${esc(story.id)}" data-asset="${esc(asset.id)}">
<label class="field">Private preview file<input type="file" name="preview" accept="image/jpeg,image/png,image/webp" required></label>
<label class="small"><input type="checkbox" name="declaration" required> I confirm this is private review only; this file does not establish source identity or publication rights.</label>
<p class="small muted">JPG, PNG or WebP, up to 25 MiB. The original is preserved privately. Production records remain unchanged.</p>
<button type="submit" class="small-button">Save private preview</button><p data-upload-status role="status" class="small"></p></form></div><div><dl class="provenance-list"><div><dt>Creator</dt><dd>${esc(asset.creator || 'Not recorded')}</dd></div><div><dt>Source</dt><dd>${external(asset.sourceUrl, 'Open original source')}</dd></div><div><dt>Provider</dt><dd>${esc(asset.provider || 'Not recorded')}</dd></div><div><dt>Recorded license</dt><dd>${esc(asset.license || 'Not recorded')}</dd></div><div><dt>Rights status</dt><dd>${badge(human(asset.rightsStatus), asset.rightsStatus === 'cleared' ? 'good' : 'warn')}</dd></div><div><dt>Dimensions</dt><dd>${asset.width && asset.height ? `${esc(asset.width)} × ${esc(asset.height)}` : 'Not recorded'}</dd></div><div><dt>Existing asset ID</dt><dd><code>${esc(asset.id)}</code></dd></div><div><dt>Story</dt><dd>${esc(story.title)}</dd></div></dl><p class="small muted">An accessible image, archive listing or source license label does not itself complete this image’s publication clearance.</p><section class="image-editorial-review"><h3>Your editorial judgment</h3><p class="small muted">Personal taste feedback, separate from rights and audience performance. This does not add or remove slides.</p>${asset.localReview?.decision==='reject'&&effective(story).selectedAssetIds.includes(asset.id)?'<p class="notice warning">This rejected image is still in the carousel. Review the sequence explicitly before production.</p>':''}
<form data-image-review data-story="${esc(story.id)}" data-asset="${esc(asset.id)}" data-version="${asset.localReview?.version||0}"><label class="field">Editorial decision<select name="decision"><option value="hold" ${asset.localReview?.decision==='hold'?'selected':''}>Hold for review</option><option value="shortlist" ${asset.localReview?.decision==='shortlist'?'selected':''}>Shortlist</option><option value="reject" ${asset.localReview?.decision==='reject'?'selected':''}>Reject for this story</option></select></label><label class="field">Why this image?<textarea name="reason" minlength="8" maxlength="1500" required>${esc(asset.localReview?.reason||'')}</textarea></label><button type="submit" class="small-button">Save editorial review</button><p data-review-status role="status" class="small"></p></form>
${asset.localReview?`<details><summary>Editorial review history (${asset.localReview.version} versions)</summary><ul>${asset.localReview.history.map(r=>`<li>Version ${r.version}: ${esc(human(r.decision))} — ${esc(r.reason)}</li>`).join('')}</ul><p class="small muted">Showing up to 50 latest decisions; earlier events remain in the private database.</p></details>`:''}</section></div></div>`;
}

export function staleDraftDialog(story) {
  const draft = effective(story);
  const known = new Set((story.media || []).map(asset => asset.id));
  const missing = draft.selectedAssetIds.filter(id => !known.has(id));
  const missingRoles = (draft.creativeBrief?.sequenceRoles || []).filter(item => !known.has(item.assetId));
  return `<div class="dialog-heading"><div><p class="eyebrow">Local draft recovery</p><h2>Review what changed.</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close draft comparison">×</button></div><p class="muted small">The source revision changed after this local draft was saved. Both copies remain available. Keeping local edits creates a new local revision; it does not update n8n.</p><div class="draft-comparison"><section><p class="eyebrow">Current source caption</p><h3>Package v${story.packageVersion || '—'}</h3><p class="body-copy">${esc(story.caption || 'No source caption recorded.')}</p><p class="small muted">${(story.selectedAssetIds || []).length} selected source images</p></section><section><p class="eyebrow">Your local caption</p><h3>Local version ${story.localDraft?.version || '—'}</h3><p class="body-copy">${esc(draft.caption || 'No local caption recorded.')}</p><p class="small muted">${draft.selectedAssetIds.length} locally selected images · ${esc(date(story.localDraft?.updatedAt))} ET</p>${draft.notes ? `<details><summary>Local notes</summary><p class="body-copy">${esc(draft.notes)}</p></details>` : ''}${draft.creativeBrief ? `<details><summary>Local creative direction</summary>${creativeBriefSummary(draft.creativeBrief)}</details>` : ''}</section></div>${missing.length ? `<div class="notice warning"><strong>${missing.length} selected image${missing.length === 1 ? ' is' : 's are'} no longer available in the current source.</strong><p>The original local version will remain in history. Keeping this proposal requires explicitly removing the unavailable image references from the new version.</p><ul>${missing.map(id => `<li><code>${esc(id)}</code></li>`).join('')}</ul></div>` : '<p class="small muted">Every locally selected asset is still present in the current source collection.</p>'}${missingRoles.length ? `<div class="notice warning"><strong>${missingRoles.length} narrative-role annotation${missingRoles.length === 1 ? ' refers' : 's refer'} to an unavailable source image.</strong><p>Keeping this draft also requires explicitly removing those unavailable annotations from the new version. The earlier creative brief remains in history.</p></div>` : ''}<div class="dialog-actions"><button class="button button-dark" data-action="rebase-draft" data-story="${esc(story.id)}">${missing.length || missingRoles.length ? `Keep local edits and review ${missing.length + missingRoles.length} unavailable reference${missing.length + missingRoles.length === 1 ? '' : 's'}` : 'Keep local edits after review'}</button><a class="button button-light" href="/api/stories/${encodeURIComponent(story.id)}/proposal" download>Download proposal before deciding ↗</a></div><p class="small muted">Earlier local versions are retained. No automatic merge or production write occurs.</p>`;
}

export function draftHistoryDialog(story, versions) {
  return `<div class="dialog-heading"><div><p class="eyebrow">Private editorial revisions</p><h2>Local version history.</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close local version history">×</button></div><p class="small muted">These are this development workspace’s local saves, not n8n workflow history or production revisions. Restoring creates another local save and preserves the versions below.</p>${versions.length ? `<div class="draft-history">${versions.map((draft, index) => `<details ${index === 0 ? 'open' : ''}><summary><strong>Version ${esc(draft.version)}</strong><span>${esc(date(draft.updatedAt))} ET · ${esc(human(draft.event || 'local save'))}</span></summary><p class="body-copy">${esc(draft.caption || 'No local caption recorded.')}</p><p class="small muted">${draft.selectedAssetIds?.length || 0} selected images${draft.musicSelection?.track ? ` · ${esc(draft.musicSelection.track)} / ${esc(draft.musicSelection.artist)}` : ''}</p>${draft.notes ? `<details><summary>Editor’s notes</summary><p class="body-copy">${esc(draft.notes)}</p></details>` : ''}${draft.creativeBrief ? `<details><summary>Creative direction</summary>${creativeBriefSummary(draft.creativeBrief)}</details>` : ''}<button class="small-button" data-action="restore-local-version" data-story="${esc(story.id)}" data-index="${index}" ${fieldDisabled(story)}>Use this version as a new local draft</button></details>`).join('')}</div>` : empty('No local versions saved yet', 'Caption, sequence, notes and music edits will create private versions here. Existing production records remain untouched.')} ${story.localDraft?.stale ? '<div class="notice warning"><strong>Source revision changed.</strong><p>Compare and resolve the stale source before restoring a prior version.</p></div>' : ''}`;
}


export function discovery(state) {
  const desk = state.workspace.discovery || { candidates: [], continuations: [] };
  const candidate = item => {
    const story = allStories(state).find(s=>s.id===item.storyId); if (!story) return '';
    return `<article class="discovery-candidate">${storyCard(story)}<div class="discovery-evidence"><p class="eyebrow">Recorded evidence · not a taste score</p><p>${item.sourceCount} source URLs · ${item.claimCount} cited claims · ${item.previewReferenceCount} image references · ${item.shortlistedCount||0} shortlisted · ${item.rejectedCount||0} rejected by you</p><details><summary>What needs editorial work</summary><ul>${item.gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></details><a class="text-link" href="${storyUrl(story.id,'direction')}">Develop the direction →</a></div></article>`;
  };
  const draft = state.researchDraft || {};
  return `${pageHeader('The research desk','Find the next extraordinary story.','Review a small slate from the existing n8n pipeline, or direct the same research engine with a creative brief.')}
  <section class="notice subtle"><strong>Research runs in n8n.</strong><p>Opening a form does not start or confirm a run. Sign in to n8n first and submit there; research uses AI credits. <a class="text-link" href="https://rickywelch.app.n8n.cloud/signin" target="_blank" rel="noopener noreferrer">Sign in to n8n ↗</a> Then refresh source here. This handoff does not enable recurring automation or publishing. Existing schedules remain managed in n8n.</p></section>
  <div class="research-layout"><section class="paper-panel">${sectionHeading('Proactive discovery','The existing n8n discovery preset develops a small source-led batch.')}<p>Use the current editorial preset, brand rules and duplicate checks. The ordinary batch requests two research candidates; downstream quality gates may save fewer. Total token cost is not available here.</p><button class="button button-dark" data-action="prepare-discovery">Prepare a discovery run</button><p class="small muted">This creates a local tracking ticket. Submission remains in the existing login-protected n8n form.</p></section>
  <section class="paper-panel">${sectionHeading('Give the research desk a direction','A subject, photograph, cultural connection or question.')}<form data-research-form><label class="field">Creative direction<textarea name="prompt" minlength="12" maxlength="2000" required placeholder="Find the story behind…">${esc(draft.prompt||'')}</textarea></label><label class="field">Source link (optional)<input type="url" name="sourceUrl" value="${esc(draft.sourceUrl||'')}" placeholder="https://…"></label><button class="button button-dark" type="submit">Save brief for n8n</button><p data-research-status role="status" class="small"></p><p class="small muted">Saved on this computer. The handoff link carries the brief to n8n in its URL; verify the prefilled fields before submitting. Do not include secrets.</p></form></section></div>
  <section>${sectionHeading('New research to review','Up to five existing n8n candidates, ordered by recorded source coverage. No audience-performance or visual-quality score is inferred.')}<div class="discovery-grid">${desk.candidates.length?desk.candidates.map(candidate).join(''):empty('No new candidates in the current snapshot','Prepare a discovery run, submit it in n8n, then use Refresh source. No example ideas are substituted.')}</div></section>
  <section>${sectionHeading('Continue a developing story','Existing work, separate from new research.')}<div class="discovery-grid">${desk.continuations.map(candidate).join('')||empty('No developing stories here','Check the main pipeline for archived or published work.')}</div></section>
  <section>${sectionHeading('Research handoffs','Private request history. A linked story is chosen by you; it does not prove which execution generated it.')}<div class="research-requests">${(state.workspace.researchRequests||[]).map(request=>researchRequest(state,request)).join('')||empty('No research handoffs saved','Prepare a discovery run or save a creative direction above.')}</div></section>`;
}
function researchRequest(state, request) {
  const linked = allStories(state).find(s=>s.id===request.linkedStoryId);
  const newStories = allStories(state).filter(s=>!request.baselineIds.includes(s.id));
  return `<article class="paper-panel research-request" data-request-id="${esc(request.id)}"><div class="section-heading"><h3>${request.kind==='brief'?'Creative brief':'Discovery run'}</h3>${badge(linked?'Existing story linked':request.version?'Handoff requested · execution unconfirmed':'Prepared locally')}</div><p class="body-copy">${esc(request.prompt)}</p><p class="small muted">${esc(date(request.createdAt))} ET · Local version ${request.version}</p><a class="button button-light" href="${esc(request.handoffUrl)}" target="_blank" rel="noopener noreferrer" data-research-handoff="${esc(request.id)}" data-version="${request.version}">Open existing n8n research form ↗</a>${linked?`<p>Linked by you: <a class="text-link" href="${storyUrl(linked.id)}">${esc(linked.title)} →</a></p>`:''}<form data-research-link data-request="${esc(request.id)}" data-version="${request.version}"><label class="field">Link a resulting story<select name="storyId" required><option value="">Choose an existing n8n story</option>${allStories(state).map(s=>`<option value="${esc(s.id)}" ${s.id===request.linkedStoryId?'selected':''}>${esc(s.title)} (${esc(s.id)})</option>`).join('')}</select></label><button class="small-button" type="submit">Link existing story</button><p data-research-status role="status" class="small"></p></form>${newStories.length?`<p class="small muted">${newStories.length} source stories appeared after this ticket was prepared. That timing does not establish attribution.</p>`:''}</article>`;
}

export function carouselRehearsal(story, index = 0, fit = 'frame') {
  const assets = mediaFor(story); const position = Math.max(0, Math.min(assets.length - 1, index));
  const asset = assets[position]; if (!asset) return empty('No slides selected', 'Choose photographs in the existing image library.');
  const draft = effective(story); const role = draft.creativeBrief?.sequenceRoles?.find(r=>r.assetId===asset.id);
  return `<section class="carousel-rehearsal" data-rehearsal data-fit="${fit==='original'?'original':'frame'}"><div class="dialog-heading"><div><p class="eyebrow">Private carousel rehearsal · ${position+1} / ${assets.length}</p><h2>${esc(story.title)}</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close carousel rehearsal">×</button></div>
  <div class="rehearsal-controls"><button class="small-button" data-action="rehearse-step" data-step="-1" ${position===0?'disabled':''} aria-label="Previous carousel image">← Previous</button><span role="status" aria-live="polite">Slide ${position+1} of ${assets.length}</span><button class="small-button" data-action="rehearse-step" data-step="1" ${position===assets.length-1?'disabled':''} aria-label="Next carousel image">Next →</button><label class="small">Framing<select data-rehearsal-fit aria-label="Framing"><option value="frame" ${fit==='original'?'':'selected'}>4:5 frame · contain</option><option value="original" ${fit==='original'?'selected':''}>Full image proportions</option></select></label></div>
  <div class="rehearsal-layout"><div class="rehearsal-stage">${image(asset,{eager:true})}</div><aside><p class="eyebrow">${position===0?'Opening photograph':`Slide ${position+1}`}</p><h3>${esc(asset.title)}</h3><p>${esc(asset.creator||'Creator not recorded')}</p>${badge(asset.rightsStatus==='cleared'?'Clearance recorded':'Rights pending',asset.rightsStatus==='cleared'?'good':'warn')}<p>${external(asset.sourceUrl,'Original source')}</p><p class="small">${asset.localPreview?`Private derivative: ${esc(asset.localPreview.width)} × ${esc(asset.localPreview.height)}; identity unverified.`:asset.width&&asset.height?`Recorded dimensions: ${esc(asset.width)} × ${esc(asset.height)}; not decoded original verification.`:'Original dimensions not recorded.'}</p><h3>Narrative purpose</h3><p>${role?esc(human(role.role)):'No narrative role assigned yet.'}</p>${role?.note?`<p>${esc(role.note)}</p>`:''}<p class="small muted">Arrow keys move between images. These framing modes are previews only: no crop, source image or export is changed. Private previews do not prove production readiness.</p></aside></div>
  <details class="rehearsal-caption"><summary>Read the current caption and music direction</summary><p class="body-copy">${esc(draft.caption||'No caption saved.')}</p><p>${draft.musicSelection?esc(`${draft.musicSelection.track} / ${draft.musicSelection.artist}`):'Music direction not selected.'}</p></details></section>`;
}
